insert into public.courses (id, slug, title, subtitle, description, category_id, level, language, accent, status, outcomes, requirements, tags, pass_mark, estimated_hours, featured, certificate_enabled, sequential, published_at)
values ($dbi$19b8b243-5033-56d0-95d6-c11478fd58cc$dbi$, $dbi$digital-literacy-essentials$dbi$, $dbi$Digital Literacy Essentials$dbi$, $dbi$Use computers, the internet and everyday digital tools with confidence — from your first click to your first professional email.$dbi$, $dbi$Digital skills are now as important as reading and writing. Whether you want to do better at school, apply for a job, run a small business or simply stay in touch with family, you need to be comfortable with computers and the internet.

This course is designed for complete beginners. Each lesson is short, uses everyday examples from Ghana and beyond, and ends with a small activity you can try right away. By the end, you will be able to use a computer confidently, find reliable information online, communicate professionally by email and keep yourself safe on the internet.$dbi$, (select id from public.categories where slug = $dbi$digital-skills$dbi$), $dbi$beginner$dbi$, 'English', null, 'published', array[$dbi$Name the main parts of a computer and explain what each one does$dbi$, $dbi$Organise files and folders so you can always find your work$dbi$, $dbi$Search the internet effectively and judge whether a source is trustworthy$dbi$, $dbi$Write and send clear, polite emails with attachments$dbi$, $dbi$Protect your accounts with strong passwords and avoid common scams$dbi$, $dbi$Use documents, spreadsheets and slides for school and work$dbi$]::text[], array[$dbi$No experience needed — this course starts from zero$dbi$, $dbi$Access to a computer, tablet or smartphone (you can study the lessons offline)$dbi$]::text[], array[$dbi$computer basics$dbi$, $dbi$internet$dbi$, $dbi$email$dbi$, $dbi$typing$dbi$, $dbi$files$dbi$, $dbi$online safety$dbi$]::text[], 70, 6, true, true, false, now())
