-- Spreadsheets & Data Analysis with Excel
insert into public.courses (id, slug, title, subtitle, description, category_id, level, language, accent, status, outcomes, requirements, tags, pass_mark, estimated_hours, featured, certificate_enabled, sequential, published_at)
values ($dbi$8ae7861b-b5f1-5a64-afaa-3115e1a70e2b$dbi$, $dbi$spreadsheets-data-analysis$dbi$, $dbi$Spreadsheets & Data Analysis with Excel$dbi$, $dbi$Go from blank grid to confident analyst — formulas, functions, charts and real-world data skills employers want.$dbi$, $dbi$Spreadsheets are the most widely used data tool in the world. Shops use them to track stock, teachers use them for marks, NGOs use them to report impact, and almost every office job asks for "good Excel skills".

In this hands-on course you will learn spreadsheets the way professionals use them. Each lesson works through a realistic example — a market trader's sales, a class mark sheet, a family budget in cedis — so you can apply what you learn straight away. Everything works in Excel, Google Sheets and LibreOffice.$dbi$, (select id from public.categories where slug = $dbi$data-analysis$dbi$), $dbi$beginner$dbi$, 'English', null, 'published', array[$dbi$Navigate a spreadsheet and enter, format and organise data correctly$dbi$, $dbi$Write formulas with relative and absolute references$dbi$, $dbi$Use essential functions such as SUM, AVERAGE, IF, COUNTIF, SUMIF and XLOOKUP$dbi$, $dbi$Clean messy data and sort, filter and validate it$dbi$, $dbi$Summarise data with PivotTables and present it with clear charts$dbi$, $dbi$Build practical tools such as a budget, a mark sheet and a sales report$dbi$]::text[], array[$dbi$Complete Digital Literacy Essentials or be comfortable using a computer$dbi$, $dbi$Microsoft Excel, Google Sheets (free) or LibreOffice Calc — all lessons work in each$dbi$]::text[], array[$dbi$excel$dbi$, $dbi$google sheets$dbi$, $dbi$formulas$dbi$, $dbi$charts$dbi$, $dbi$data analysis$dbi$, $dbi$budgeting$dbi$]::text[], 70, 8, true, true, false, now())
