-- Python Programming for Beginners
insert into public.courses (id, slug, title, subtitle, description, category_id, level, language, accent, status, outcomes, requirements, tags, pass_mark, estimated_hours, featured, certificate_enabled, sequential, published_at)
values ($dbi$101c2d82-03a8-5624-a00d-13c950d5c3eb$dbi$, $dbi$python-programming-beginners$dbi$, $dbi$Python Programming for Beginners$dbi$, $dbi$Learn to think like a programmer and write real Python programs — from your first print statement to a working mini-project.$dbi$, $dbi$Python is one of the world's most popular programming languages. It's used by Google, NASA, banks, data scientists and AI researchers — and it is famously easy to read, which makes it perfect as a first language.

In this course you will learn the core ideas of programming that apply to every language: variables, decisions, loops, functions and data structures. Every lesson has short examples you can run immediately, and the course ends with a project you can show off. Think of it as learning to give clear instructions to a very fast, very literal assistant.$dbi$, (select id from public.categories where slug = $dbi$software-development$dbi$), $dbi$beginner$dbi$, 'English', null, 'published', array[$dbi$Write, run and debug Python programs$dbi$, $dbi$Use variables, data types, input and output$dbi$, $dbi$Control program flow with conditions and loops$dbi$, $dbi$Organise code with functions and store data in lists and dictionaries$dbi$, $dbi$Read and handle errors calmly and fix bugs systematically$dbi$, $dbi$Build a complete command-line project such as a quiz game or budget tracker$dbi$]::text[], array[$dbi$Basic computer skills$dbi$, $dbi$Python 3 installed, or a free online editor such as Programiz (link in the Resource library)$dbi$]::text[], array[$dbi$python$dbi$, $dbi$programming$dbi$, $dbi$coding$dbi$, $dbi$algorithms$dbi$, $dbi$problem solving$dbi$]::text[], 70, 12, false, true, false, now())
