-- Graphic Design Essentials with Canva
insert into public.courses (id, slug, title, subtitle, description, category_id, level, language, accent, status, outcomes, requirements, tags, pass_mark, estimated_hours, featured, certificate_enabled, sequential, published_at)
values ($dbi$c7f62e0d-7882-5030-a605-b53eccabda8c$dbi$, $dbi$graphic-design-essentials$dbi$, $dbi$Graphic Design Essentials with Canva$dbi$, $dbi$Learn the principles professional designers use and create stunning flyers, social posts and logos with free tools.$dbi$, $dbi$Good design helps a message get noticed and understood. Churches, schools, small businesses and NGOs all need flyers, posters and social media graphics — and people who can design them well are always in demand.

This course teaches the timeless principles of graphic design, then shows you how to apply them with Canva, a free design tool that works on phones and computers. You'll finish with a set of real designs for your portfolio and a brand kit you can use for your own projects or clients.$dbi$, (select id from public.categories where slug = $dbi$graphics-multimedia$dbi$), $dbi$beginner$dbi$, 'English', null, 'published', array[$dbi$Apply the core design principles — hierarchy, contrast, alignment, repetition, proximity and white space$dbi$, $dbi$Choose and pair fonts that are readable and match the message$dbi$, $dbi$Build colour palettes that look professional and are accessible$dbi$, $dbi$Design flyers, social media posts and simple logos in Canva$dbi$, $dbi$Use images legally and export designs in the right format for print or screen$dbi$, $dbi$Create a mini brand kit and a portfolio of design work$dbi$]::text[], array[$dbi$Basic computer or smartphone skills$dbi$, $dbi$A free Canva account (works in a browser or the Canva app)$dbi$]::text[], array[$dbi$graphic design$dbi$, $dbi$canva$dbi$, $dbi$typography$dbi$, $dbi$colour$dbi$, $dbi$branding$dbi$, $dbi$social media$dbi$]::text[], 70, 7, false, true, false, now())
