insert into public.modules (id, course_id, title, summary, position) values ($dbi$104f144d-6ad9-52f5-86f2-58436d2b97fc$dbi$, $dbi$c7f62e0d-7882-5030-a605-b53eccabda8c$dbi$, $dbi$The principles of good design$dbi$, $dbi$Learn the rules that make designs look professional — whatever tool you use.$dbi$, 1)
