-- Cybersecurity Basics: Stay Safe Online
insert into public.courses (id, slug, title, subtitle, description, category_id, level, language, accent, status, outcomes, requirements, tags, pass_mark, estimated_hours, featured, certificate_enabled, sequential, published_at)
values ($dbi$65adf730-0e16-5c8a-b73b-454f247ee74c$dbi$, $dbi$cybersecurity-basics$dbi$, $dbi$Cybersecurity Basics: Stay Safe Online$dbi$, $dbi$Protect your accounts, devices, money and privacy — and understand how attackers think.$dbi$, $dbi$Cybercrime is growing fast in Ghana and around the world. Criminals steal mobile money, take over WhatsApp and Facebook accounts, and trick people into handing over passwords and personal information. Most attacks succeed not because of clever hacking, but because people don't know the warning signs.

This practical course teaches you how attacks work and exactly what to do to protect yourself, your family and your workplace. It's also the perfect first step if you are curious about a career in cybersecurity — one of the fastest-growing fields in technology.$dbi$, (select id from public.categories where slug = $dbi$cybersecurity$dbi$), $dbi$beginner$dbi$, 'English', null, 'published', array[$dbi$Explain the main cyber threats people and organisations face$dbi$, $dbi$Create strong passwords and secure accounts with multi-factor authentication$dbi$, $dbi$Recognise phishing, social engineering and mobile-money scams$dbi$, $dbi$Keep phones and computers protected from malware$dbi$, $dbi$Protect your privacy and data on social media and public Wi-Fi$dbi$, $dbi$Respond correctly if an account is hacked or data is leaked$dbi$]::text[], array[$dbi$Basic computer or smartphone skills$dbi$, $dbi$No technical background needed$dbi$]::text[], array[$dbi$cybersecurity$dbi$, $dbi$passwords$dbi$, $dbi$phishing$dbi$, $dbi$mobile money$dbi$, $dbi$privacy$dbi$, $dbi$malware$dbi$]::text[], 70, 6, false, true, false, now())
