insert into public.courses (id, slug, title, subtitle, description, category_id, level, language, accent, status, outcomes, requirements, tags, pass_mark, estimated_hours, featured, certificate_enabled, sequential, published_at)
values ($dbi$91c27293-1143-5c17-acd9-7ed8da4d140b$dbi$, $dbi$digital-marketing-social-media$dbi$, $dbi$Digital Marketing & Social Media$dbi$, $dbi$Grow a business, brand or cause online — strategy, content, WhatsApp Business, ads and analytics.$dbi$, $dbi$Most customers now discover products and services on their phones. A tailor in Kumasi, a chop bar in Takoradi, a church youth programme or a start-up in Accra can all reach thousands of people online — often for free.

This practical course teaches you how to plan, create and measure digital marketing that actually brings results. You will build a marketing plan for a real or imaginary business and learn skills that small businesses are actively looking to hire for.$dbi$, (select id from public.categories where slug = $dbi$digital-marketing$dbi$), $dbi$beginner$dbi$, 'English', null, 'published', array[$dbi$Explain how digital marketing works and how it differs from traditional marketing$dbi$, $dbi$Define a target audience and write a simple marketing plan with SMART goals$dbi$, $dbi$Create engaging content for Facebook, Instagram, TikTok and WhatsApp$dbi$, $dbi$Set up and use WhatsApp Business and Google Business Profile$dbi$, $dbi$Understand the basics of SEO, email marketing and paid ads$dbi$, $dbi$Measure results with analytics and improve your campaigns$dbi$]::text[], array[$dbi$A smartphone or computer with internet access$dbi$, $dbi$Basic social media experience is helpful but not required$dbi$]::text[], array[$dbi$digital marketing$dbi$, $dbi$social media$dbi$, $dbi$whatsapp business$dbi$, $dbi$content$dbi$, $dbi$seo$dbi$, $dbi$ads$dbi$, $dbi$analytics$dbi$]::text[], 70, 7, false, true, false, now())
