-- Computer Networks & Cloud Basics
insert into public.courses (id, slug, title, subtitle, description, category_id, level, language, accent, status, outcomes, requirements, tags, pass_mark, estimated_hours, featured, certificate_enabled, sequential, published_at)
values ($dbi$fb06f556-2356-5219-9b76-724c8429be56$dbi$, $dbi$networks-and-cloud-basics$dbi$, $dbi$Computer Networks & Cloud Basics$dbi$, $dbi$Understand how devices connect, how the internet really works and how cloud services power modern life.$dbi$, $dbi$Every time you send a WhatsApp message, pay with mobile money or join a video lesson, your data travels through dozens of networks and data centres in a fraction of a second. Networks and the cloud are the invisible infrastructure of modern life.

This course explains, in plain language, how networks and the internet work, how to set up and fix Wi-Fi, and what "the cloud" actually is. It is a strong foundation for careers in IT support, network engineering, cloud computing and cybersecurity.$dbi$, (select id from public.categories where slug = $dbi$network-cloud$dbi$), $dbi$beginner$dbi$, 'English', null, 'published', array[$dbi$Describe the main types of networks and the devices that build them$dbi$, $dbi$Explain IP addresses, DNS and how data travels across the internet$dbi$, $dbi$Set up and troubleshoot a home or small-office Wi-Fi network$dbi$, $dbi$Understand cloud computing models and everyday cloud services$dbi$, $dbi$Choose between local, cloud and hybrid storage sensibly$dbi$, $dbi$Plan a simple, secure network for a small school or business$dbi$]::text[], array[$dbi$Digital Literacy Essentials or equivalent computer skills$dbi$, $dbi$Curiosity about how things work — no technical background needed$dbi$]::text[], array[$dbi$networking$dbi$, $dbi$internet$dbi$, $dbi$wifi$dbi$, $dbi$ip address$dbi$, $dbi$dns$dbi$, $dbi$cloud computing$dbi$]::text[], 70, 6, false, true, false, now())
