-- Artificial Intelligence for Everyone
insert into public.courses (id, slug, title, subtitle, description, category_id, level, language, accent, status, outcomes, requirements, tags, pass_mark, estimated_hours, featured, certificate_enabled, sequential, published_at)
values ($dbi$e2c4f975-0315-5733-a3d3-16c77726f249$dbi$, $dbi$ai-for-everyone$dbi$, $dbi$Artificial Intelligence for Everyone$dbi$, $dbi$Understand what AI is, how it works, and how to use AI tools wisely and responsibly for learning and work.$dbi$, $dbi$Artificial intelligence is changing how we learn, work and communicate. AI assistants can explain homework, draft emails and write code; AI systems help diagnose diseases, translate languages and detect fraud. Knowing how to use AI well — and how to question it — is becoming an essential skill for everyone.

This course explains AI in plain language, shows you how to get great results from AI tools, and helps you think critically about AI's limits and risks. It's designed for complete beginners and is a perfect companion to any other course on DBI Learn.$dbi$, (select id from public.categories where slug = $dbi$artificial-intelligence$dbi$), $dbi$beginner$dbi$, 'English', null, 'published', array[$dbi$Explain in simple terms what artificial intelligence and machine learning are$dbi$, $dbi$Recognise everyday uses of AI in Ghana and around the world$dbi$, $dbi$Write clear prompts that get useful results from AI assistants$dbi$, $dbi$Use AI to study, create and work more effectively — without cheating$dbi$, $dbi$Spot AI mistakes, bias, deepfakes and misinformation$dbi$, $dbi$Discuss the opportunities and risks of AI for jobs and society$dbi$]::text[], array[$dbi$Basic computer or smartphone skills$dbi$, $dbi$Curiosity — no maths or programming needed$dbi$]::text[], array[$dbi$artificial intelligence$dbi$, $dbi$machine learning$dbi$, $dbi$chatgpt$dbi$, $dbi$prompting$dbi$, $dbi$ethics$dbi$, $dbi$generative ai$dbi$]::text[], 70, 5, true, true, false, now())
on conflict (id) do update set slug = excluded.slug, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, level = excluded.level, accent = excluded.accent, outcomes = excluded.outcomes, requirements = excluded.requirements, tags = excluded.tags, pass_mark = excluded.pass_mark, estimated_hours = excluded.estimated_hours, featured = excluded.featured, sequential = excluded.sequential;
